/* ------------------------------------------------------------ journey */
function journey() {
  const steps = $("#j-steps"), panel = $("#j-panel"), svg = $("#j-path");
  steps.insertAdjacentHTML("beforeend", STEPS.map((s, i) => `<div class="jstep" data-i="${i}"><div class="node">${s.i}</div><span>${s.n}</span></div>`).join(""));
  let cur = 0, playing = true, timer, marks = [], headLen = 0, total = 1, raf = 0, seen = false;
  const NS = "http://www.w3.org/2000/svg";
  const mk = (tag, cls) => { const e = document.createElementNS(NS, tag); if (cls) e.setAttribute("class", cls); return e; };
  const defs = mk("defs"), base = mk("path", "j-base"), flow = mk("path", "j-flow"), glow = mk("path", "j-glow"), prog = mk("path", "j-prog"), head = mk("path", "j-head");
  defs.innerHTML = `<linearGradient id="jg" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="1000" y2="0"><stop offset="0" stop-color="#22d3ee"/><stop offset=".55" stop-color="#8b5cf6"/><stop offset="1" stop-color="#f472b6"/></linearGradient>`;
  head.setAttribute("d", "M0 0 L-15 -7.5 L-11 0 L-15 7.5 Z");
  svg.append(defs, base, flow, glow, prog, head);

  // one continuous path through the stage centres; when the grid wraps, it loops out to the right,
  // runs back below the labels and enters the next row from the left, so it reads like a snake
  function layout() {
    const box = steps.getBoundingClientRect();
    if (!box.width) return;
    const N = $$(".jstep", steps).map(st => {
      const n = $(".node", st), b = n.getBoundingClientRect(), r = n.offsetWidth / 2;
      return { x: b.left - box.left + b.width / 2, y: b.top - box.top + b.height / 2, r, top: b.top - box.top + b.height / 2 - r, bottom: st.getBoundingClientRect().bottom - box.top };
    });
    svg.setAttribute("viewBox", `0 0 ${box.width} ${box.height}`);
    $("#jg", defs).setAttribute("x2", box.width);
    let d = `M ${N[0].x} ${N[0].y}`;
    const parts = [d];
    for (let k = 1; k < N.length; k++) {
      const a = N[k - 1], b = N[k];
      if (Math.abs(a.y - b.y) < 4) d = ` L ${b.x} ${b.y}`;
      else {
        const o1 = Math.max(8, Math.min(30, box.width - a.x - a.r - 4)), o2 = Math.max(8, Math.min(30, b.x - b.r - 4));
        const xr = a.x + a.r + o1, xl = b.x - b.r - o2, gy = (a.bottom + b.top) / 2, R = Math.max(2, Math.min(14, (gy - a.y) / 2, (b.y - gy) / 2));
        d = ` L ${xr - R} ${a.y} Q ${xr} ${a.y} ${xr} ${a.y + R} L ${xr} ${gy - R} Q ${xr} ${gy} ${xr - R} ${gy} L ${xl + R} ${gy} Q ${xl} ${gy} ${xl} ${gy + R} L ${xl} ${b.y - R} Q ${xl} ${b.y} ${xl + R} ${b.y} L ${b.x} ${b.y}`;
      }
      parts.push(d);
    }
    const full = parts.join("");
    [base, flow, glow, prog].forEach(p => p.setAttribute("d", full));
    total = base.getTotalLength();
    // arrow tip stops just outside each stage it is heading into
    marks = N.map((n, k) => {
      if (!k) return n.r + 18;
      base.setAttribute("d", parts.slice(0, k + 1).join(""));
      return base.getTotalLength() - n.r - 8;
    });
    base.setAttribute("d", full);
    prog.style.strokeDasharray = glow.style.strokeDasharray = `${total} ${total}`;
    place(marks[cur]);
  }
  function place(L) {
    headLen = L;
    const p = base.getPointAtLength(L), q = base.getPointAtLength(Math.max(0, L - 2));
    head.setAttribute("transform", `translate(${p.x} ${p.y}) rotate(${Math.atan2(p.y - q.y, p.x - q.x) * 180 / Math.PI})`);
    prog.style.strokeDashoffset = glow.style.strokeDashoffset = total - L;
  }
  function glide(to) {
    cancelAnimationFrame(raf);
    if (reduce || !marks.length) return place(to);
    if (to < headLen) {                       // looping back to the start: fade out, jump, fade in
      head.style.opacity = 0;
      setTimeout(() => { place(to); head.style.opacity = 1; }, 350);
      return;
    }
    const from = headLen, t0 = performance.now(), dur = 1100;
    const step = t => { const k = Math.min(1, (t - t0) / dur), e = k < .5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2; place(from + (to - from) * e); if (k < 1) raf = requestAnimationFrame(step); };
    raf = requestAnimationFrame(step);
  }
  const show = i => {
    cur = i;
    $$(".jstep").forEach((el, k) => { el.classList.toggle("active", k === i); el.classList.toggle("done", k < i); });
    panel.innerHTML = `<h4>${STEPS[i].i} ${STEPS[i].t}</h4><p>${STEPS[i].p}</p>`;
    if (marks.length) glide(marks[i]);
  };
  const loop = () => { clearInterval(timer); timer = setInterval(() => { if (playing && seen && !document.hidden) show((cur + 1) % STEPS.length); }, 3600); };
  steps.addEventListener("click", e => { const s = e.target.closest(".jstep"); if (s) { show(+s.dataset.i); loop(); } });
  $("#j-toggle").onclick = e => { playing = !playing; e.target.textContent = playing ? "❚❚ Pause" : "▶ Play"; };
  new ResizeObserver(layout).observe(steps);
  new IntersectionObserver(es => { seen = es[0].isIntersecting; }).observe(steps);
  show(0); layout(); loop();
}

/* ------------------------------------------------------------ architecture diagrams */
function arch() {
  const L = (cls, a, b, i) => `<div class="layer ${cls}" style="--i:${i}"><b>${a}</b>${b}</div>`;
  let i = 0;
  const paper = [L("io", "Input", "100×100×3", i++)];
  [98, 96, 48, 46, 44, 22, 20, 18, 9, 7, 5, 2].forEach((s, k) => {
    const pool = [2, 5, 8, 11].includes(k);
    paper.push(L(pool ? "pool" : "conv", pool ? "Pool" : "Conv·32", `${s}²`, i++));
  });
  paper.push(L("fc", "Dropout", "0.5", i++), L("fc", "Flatten", "128", i++), L("fc", "Dense", "64·ReLU", i++), L("io", "Softmax", "2 classes", i++));
  i = 0;
  const plus = [L("io", "Input", "100×100×3", i++), L("conv", "Stem", "Conv·BN·ReLU", i++), L("pool", "Pool", "50×50", i++),
    L("res", "Res-SE", "24→32", i++), L("pool", "Pool", "25×25", i++), L("res", "Res-SE", "32→48", i++), L("pool", "Pool", "12×12", i++),
    L("res", "Res-SE", "48→64", i++), L("pool", "Pool", "6×6", i++), L("res", "Res-SE", "64→96", i++), L("fc", "Global avg", "96-d", i++), L("fc", "Dropout", "0.3", i++), L("io", "Dense", "2 classes", i++)];
  const pp = (R.imaging && (R.imaging.xray || R.imaging.ct) || {});
  $("#arch").innerHTML = `
    <div class="arch-row"><h4><b>Paper CNN</b> 8 conv · 4 pool · dropout · dense <span class="chip">${(pp.paper_params || 74018).toLocaleString()} params</span><span class="chip">Adam · plain</span></h4><div class="layers">${paper.join("")}</div></div>
    <div class="arch-row"><h4><b>CovidNet-Plus</b> residual · squeeze-excitation · BN · GAP <span class="chip">${(pp.plus_params || 0).toLocaleString()} params</span><span class="chip">AdamW · OneCycle · aug · LS · TTA</span></h4><div class="layers">${plus.join("")}</div></div>`;
}

/* ------------------------------------------------------------ imaging section */
/* results of `imaging.py --profile paper` (exact published protocol, Paper CNN only) */
function imagingPaper() {
  const r = (R.imaging_paper || {})[mod], el = $("#img-paper");
  el.hidden = !r; if (!r) return;
  const m = r.models["Paper CNN"], P = R.paper[mod].CNN, sm = r.smote_enn;
  const td = (k, d = 2) => `<td>${fx(m[k], d)}${r.folds > 1 && m[k + "_std"] != null ? `<em>±${fx(m[k + "_std"], d)}</em>` : ""}${P[k] != null ? `<s>${fx(P[k], d)}</s>` : ""}</td>`;
  el.innerHTML = `<h3>Paper-exact protocol <small>profile “${r.profile}” · ${r.epochs} epochs · ${r.folds}-fold CV · ${r.device} · paper in grey</small></h3>
    <p class="note">Same recipe as the paper: SMOTE-ENN applied to all ${(sm.before.covid + sm.before.non_covid).toLocaleString()} images before splitting
    (COVID ${sm.before.covid.toLocaleString()} / non-COVID ${sm.before.non_covid.toLocaleString()} → ${sm.after.covid.toLocaleString()} / ${sm.after.non_covid.toLocaleString()}),
    plain 90/10 stratified folds, Adam lr 1e-4, batch 16, fixed epochs, no early stopping. Because synthetic images are made before the split, test folds contain
    interpolations of training images, so these numbers are optimistic in the same way as the paper's.</p>
    <div class="table-scroll"><table><thead><tr><th>Model</th><th>Accuracy</th><th>Sens.</th><th>Spec.</th><th>Prec.</th><th>FDR</th><th>AUC</th><th>ms/img</th></tr></thead>
    <tbody><tr class="best"><td>Paper CNN</td>${td("accuracy")}${td("sensitivity")}${td("specificity")}${td("precision")}${td("fdr")}${td("auc", 4)}${td("ms")}</tr></tbody></table></div>`;
}

function imaging() {
  const r = IM();
  imagingPaper();
  if (!r) { $("#img-kpis").innerHTML = `<div class="glass kpi"><small>Pending</small><div class="s">${(R.imaging_paper || {})[mod] ? "Only the paper-exact run exists for this modality — see “Paper-exact protocol” below." : "Run imaging.py then export_site.py to populate this section."}</div></div>`; return; }
  const ep = r.history.paper.length, epPlus = r.history.plus.length;
  const ipm = (R.imaging_paper || {})[mod], ipx = ipm && ipm.models["Paper CNN"];
  $("#img-note").innerHTML = `<b>How to read these numbers.</b> The charts compare eight models from the “${r.profile}” run: the paper CNN for ${ep} epochs and CovidNet-Plus for ${epPlus}, on ${r.folds} held-out 10% fold${r.folds > 1 ? "s" : ""}, with class-weighted loss instead of synthetic images.` +
    (ipx ? ` The paper CNN was also re-run with the paper's exact protocol (100 epochs, 10 folds, SMOTE-ENN): <b>${fx(ipx.accuracy)}% ± ${fx(ipx.accuracy_std)}</b> against the paper's ${fx(R.paper[mod].CNN.accuracy)}%. That run is in the table at the end of this section, and <a href="#numbers" style="color:var(--cyan)">section 09</a> explains the gap.` : "");
  const M = r.models, P = R.paper[mod], best = IMG_ORDER.reduce((a, k) => (M[k] && (!a || M[k].accuracy > M[a].accuracy) ? k : a), null);
  const d = M[best].accuracy - M["Paper CNN"].accuracy;
  $("#img-kpis").innerHTML = [
    ipx ? ["Paper CNN · paper protocol, 10-fold", fx(ipx.accuracy), `± ${fx(ipx.accuracy_std)} · paper reports ${fx(P.CNN.accuracy)}%`, C.cyan, ipx.accuracy]
        : ["Paper CNN · reproduced", fx(M["Paper CNN"].accuracy), `paper reports ${fx(P.CNN.accuracy)}%`, C.cyan, M["Paper CNN"].accuracy],
    ["Best model · " + IMG_LABEL[best] + " · one fold", fx(M[best].accuracy), `<span class="${d >= 0 ? "up-t" : "dn-t"}">${d >= 0 ? "▲" : "▼"} ${fx(Math.abs(d))} pt vs paper CNN, same run</span>`, C.green, M[best].accuracy],
    ["AUC · " + IMG_LABEL[best], fx(M[best].auc, 4), `sensitivity ${fx(M[best].sensitivity)}% · specificity ${fx(M[best].specificity)}%`, C.violet, null],
    ["Calibration (ECE)", fx(r.calibration.after, 3), `from ${fx(r.calibration.before, 3)} · T = ${fx(r.calibration.temperature)}`, C.pink, null],
  ].map(k => `<div class="glass kpi tilt"><small>${k[0]}</small><div class="v" style="color:${k[3]}">${k[4] != null ? `<span data-to="${k[1]}" data-dec="2">0</span>%` : k[1]}</div><div class="s">${k[2]}</div></div>`).join("");
  watchCounts($("#img-kpis")); tiltInit();

  // grouped accuracy bars
  const labs = IMG_ORDER.map(k => IMG_LABEL[k]);
  chart("ch-img-bar", { type: "bar", data: { labels: labs, datasets: [
    { label: "Paper reported", data: IMG_ORDER.map(k => IMG_PAPER_KEY[k] ? P[IMG_PAPER_KEY[k]].accuracy : null), backgroundColor: "rgba(139,148,179,.45)", borderRadius: 6 },
    { label: "Reproduced / ours", data: IMG_ORDER.map(k => M[k] ? M[k].accuracy : null), backgroundColor: ctx => { const g = ctx.chart.ctx.createLinearGradient(0, 300, 0, 0); g.addColorStop(0, C.violet); g.addColorStop(1, C.cyan); return g; }, borderRadius: 6 }] },
    options: { maintainAspectRatio: false, scales: { y: { min: Math.floor(Math.min(80, ...IMG_ORDER.map(k => M[k] ? M[k].accuracy : 100)) / 5) * 5, max: 100, title: { display: true, text: "accuracy %" } }, x: { ticks: { maxRotation: 40, font: { size: 11 } } } }, plugins: { tooltip: { callbacks: { label: c => `${c.dataset.label}: ${fx(c.parsed.y)}%` } } } } });

  // ROC
  const show = ["Paper CNN", "CNN+HGB", "CovidNet-Plus", "Plus Ensemble (calibrated)"], col = [C.grey, C.amber, C.cyan, C.pink];
  chart("ch-img-roc", { type: "line", data: { datasets: [...show.map((k, i) => ({ label: `${IMG_LABEL[k]} (AUC ${fx(M[k].auc, 4)})`, data: M[k].roc.fpr.map((x, j) => ({ x, y: M[k].roc.tpr[j] })), borderColor: col[i], backgroundColor: "transparent", borderWidth: 2.2, pointRadius: 0, tension: .1 })),
    { label: "chance", data: [{ x: 0, y: 0 }, { x: 1, y: 1 }], borderColor: "rgba(255,255,255,.2)", borderDash: [5, 5], pointRadius: 0, borderWidth: 1 }] },
    options: { maintainAspectRatio: false, parsing: false, scales: { x: { type: "linear", min: 0, max: 1, title: { display: true, text: "false-positive rate" } }, y: { min: 0, max: 1.02, title: { display: true, text: "true-positive rate" } } }, plugins: { legend: { position: "bottom" } } } });

  curves("val_acc");
  confusion(best);
  $("#cm-name").textContent = "· " + IMG_LABEL[best];

  const pm = { "Paper CNN": r.paper_params, "CovidNet-Plus": r.plus_params, "MobileNet": 4.2e6, "DenseNet121": 8e6, "VGG-16": 138e6 };
  const lg = v => Math.log10(v), lo = 4, hi = 8.3;
  $("#img-calib").innerHTML = `<div class="mini">
    <div class="row"><span>Ensemble weight (CNN)</span><b>${fx(r.ensemble.w_cnn, 1)}</b></div>
    <div class="row"><span>Temperature T</span><b>${fx(r.calibration.temperature, 2)}</b></div>
    <div class="row"><span>ms / image (${r.device.length > 22 ? "device" : r.device})</span><b>${fx(M["Paper CNN"].ms, 2)} · ${fx(M["CovidNet-Plus"].ms, 2)}</b></div>
    <div class="row"><span>Trained for</span><b>${r.folds} fold${r.folds > 1 ? "s" : ""} · ${r.profile}</b></div></div>
    <div class="bars params-bar" style="margin-top:18px">${Object.entries(pm).map(([k, v]) => `<div class="bar-row" style="grid-template-columns:96px 1fr 62px"><span>${k}</span><div class="bar"><i data-w="${100 * (lg(v) - lo) / (hi - lo)}"></i></div><span>${v >= 1e6 ? (v / 1e6).toFixed(1) + "M" : Math.round(v / 1e3) + "k"}</span></div>`).join("")}</div>
    <p style="font-size:11px;color:var(--muted);margin-top:8px">parameters, log scale</p>`;
  requestAnimationFrame(() => setTimeout(() => $$("#img-calib .bar i").forEach(b => b.style.width = b.dataset.w + "%"), 50));

  // table
  const best1 = best;
  $("#img-table").innerHTML = `<thead><tr><th>Model</th><th>Accuracy</th><th title="(sens + spec) / 2; the paper's sensitivity and specificity columns are both this macro average">Bal. acc. (macro recall)</th><th>Sens.</th><th>Spec.</th><th title="mean of COVID and non-COVID precision, as the paper reports">Prec. (macro)</th><th>FDR (macro)</th><th>AUC</th><th>ECE</th><th>ms/img</th></tr></thead><tbody>` +
    IMG_ORDER.filter(k => M[k]).map(k => { const m = M[k], pk = IMG_PAPER_KEY[k] && P[IMG_PAPER_KEY[k]];
      const pv = key => pk ? `<s>${fx(pk[key])}</s>` : "";
      // the paper's sens = spec in every row: a two-class macro average, i.e. balanced accuracy; compare like with like
      const [[tn, fp], [fn, tp]] = m.cm || [[0, 0], [0, 0]], mprec = m.precision_macro != null ? m.precision_macro : m.cm ? 50 * (tp / Math.max(tp + fp, 1) + tn / Math.max(tn + fn, 1)) : m.precision;
      return `<tr class="${k === best1 ? "best" : ""}"><td>${IMG_LABEL[k]}</td><td>${fx(m.accuracy)}${r.folds > 1 ? `<em>±${fx(m.accuracy_std)}</em>` : ""}${pv("accuracy")}</td><td>${fx(m.balanced_accuracy != null ? m.balanced_accuracy : (m.sensitivity + m.specificity) / 2)}${pv("sensitivity")}</td><td>${fx(m.sensitivity)}</td><td>${fx(m.specificity)}</td><td>${fx(mprec)}${pv("precision")}</td><td>${fx(100 - mprec)}${pv("fdr")}</td><td>${fx(m.auc, 4)}</td><td>${fx(m.ece, 3)}</td><td>${fx(m.ms, 2)}${pv("ms")}</td></tr>`; }).join("") + "</tbody>";
}

function curves(key) {
  const r = IM(); if (!r) return;
  const h = r.history, n = Math.max(h.paper.length, h.plus.length);
  const mk = (arr, c, label) => ({ label, data: arr.map(e => e[key]), borderColor: c, backgroundColor: ctx => lineGrad(ctx.chart.ctx, c), fill: true, borderWidth: 2.2, pointRadius: 0, tension: .3 });
  chart("ch-img-curve", { type: "line", data: { labels: Array.from({ length: n }, (_, i) => i + 1), datasets: [mk(h.paper, C.grey, "Paper CNN"), mk(h.plus, C.cyan, "CovidNet-Plus")] },
    options: { maintainAspectRatio: false, scales: { x: { title: { display: true, text: "epoch" } }, y: { title: { display: true, text: key === "val_acc" ? "validation accuracy" : "validation loss" } } }, plugins: { legend: { position: "bottom" } } } });
}

function confusion(name) {
  const r = IM(), cm = r.models[name].cm, tot = cm.flat().reduce((a, b) => a + b, 0);
  const cell = (v, ok, a, b) => `<div class="cell ${ok ? "good" : "bad"}" style="--a:${v / tot * (ok ? 1.6 : 8)}"><div><span data-to="${v}">0</span><small>${a}</small></div></div>`;
  $("#cm").innerHTML = `<div></div><div class="lab">pred Non-COVID</div><div class="lab">pred COVID</div>
    <div class="lab">true Non-COVID</div>${cell(cm[0][0], 1, "TN")}${cell(cm[0][1], 0, "FP")}
    <div class="lab">true COVID</div>${cell(cm[1][0], 0, "FN")}${cell(cm[1][1], 1, "TP")}`;
  watchCounts($("#cm"));
}

/* ------------------------------------------------------------ explainability */
let gal = [], cur = null, method = "plus";
function xai() {
  gal = [...((R.gallery || {}).xray || []).map(g => ({ ...g, mod: "X-ray" })), ...((R.gallery || {}).ct || []).map(g => ({ ...g, mod: "CT" }))];
  if (!gal.length) { $("#xai-info").innerHTML = "<div>Run imaging.py to generate the gallery.</div>"; return; }
  $("#xai-thumbs").innerHTML = gal.map((g, i) => `<div class="thumb" data-i="${i}"><img loading="lazy" src="assets/gradcam/${g.id}_orig.jpg" alt=""><i class="${g.correct ? "" : "bad"}">${g.mod} · ${g.correct ? g.truth : "✕ missed"}</i></div>`).join("");
  $("#xai-thumbs").onclick = e => { const t = e.target.closest(".thumb"); if (t) selectCase(+t.dataset.i); };
  $("#xai-method").onclick = e => { const b = e.target.closest("button"); if (!b) return; method = b.dataset.k; $$("#xai-method button").forEach(x => x.classList.toggle("active", x === b)); selectCase(cur, true); };
  const box = $("#compare");
  const move = x => { const b = box.getBoundingClientRect(), p = Math.max(0, Math.min(100, 100 * (x - b.left) / b.width)); setSplit(p); };
  let drag = false;
  box.addEventListener("pointerdown", e => { drag = true; box.setPointerCapture(e.pointerId); move(e.clientX); });
  box.addEventListener("pointermove", e => drag && move(e.clientX));
  box.addEventListener("pointerup", () => drag = false);
  selectCase(0);
  if (!reduce) { let t = 0; const sw = () => { t += .035; if (t < Math.PI * 2 && !drag) { setSplit(50 + 40 * Math.sin(t * 1.0)); requestAnimationFrame(sw); } }; setTimeout(sw, 800); }
}
function setSplit(p) { $(".cmp-top").style.clipPath = `inset(0 0 0 ${p}%)`; $("#cmp-handle").style.left = p + "%"; }
function selectCase(i, keep) {
  cur = i; const g = gal[i];
  $$(".thumb").forEach((t, k) => t.classList.toggle("on", k === i));
  $("#cmp-base").src = `assets/gradcam/${g.id}_orig.jpg`;
  $("#cmp-over").src = `assets/gradcam/${g.id}_${method}.jpg`;
  $("#cmp-right-tag").textContent = method === "plus" ? "Grad-CAM++ · CovidNet-Plus" : "Grad-CAM · paper CNN";
  const pred = g.p_ens >= .5 ? "COVID" : "Non-COVID";
  $("#xai-info").innerHTML = `<div><small>Ground truth</small><b>${g.truth}</b></div><div><small>Ensemble says</small><b style="color:${g.correct ? C.green : C.red}">${pred}</b></div><div><small>P(COVID) paper CNN</small><b>${fx(g.p_paper * 100, 1)}%</b></div><div><small>P(COVID) ensemble</small><b>${fx(g.p_ens * 100, 1)}%</b></div>`;
  if (!keep) setSplit(55);
}

